package org.apache.commons.codec.net;

import java.io.*;
import java.io.ByteArrayOutputStream;
import java.io.UnsupportedEncodingException;
import java.math.*;
import java.util.*;
import java.util.BitSet;
import org.apache.commons.codec.BinaryDecoder;
import org.apache.commons.codec.BinaryEncoder;
import org.apache.commons.codec.CharEncoding;
import org.apache.commons.codec.DecoderException;
import org.apache.commons.codec.EncoderException;
import org.apache.commons.codec.StringDecoder;
import org.apache.commons.codec.StringEncoder;
import org.apache.commons.codec.binary.StringUtils;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

public class QuotedPrintableCodec_decode_TriageGen2Test {

    private QuotedPrintableCodec codec;

    @Before
    public void setUp() {
        codec = new QuotedPrintableCodec();
    }

    @Test
    public void testDecode_NullInput() throws DecoderException {
        Object result = codec.decode(null);
        assertNull("Decoding null should return null", result);
    }

    @Test
    public void testDecode_ByteArrayInput() throws DecoderException {
        // "=3D" is "=" in quoted-printable
        byte[] input = new byte[]{ '=', '3', 'D' };
        byte[] expected = "=".getBytes();

        Object result = codec.decode(input);

        assertEquals("Decoding byte array should return decoded byte array", 
                expected, result);
    }

    @Test
    public void testDecode_StringInput() throws DecoderException {
        String input = "=3D";
        String expected = "=";

        Object result = codec.decode(input);

        assertEquals("Decoding String should return decoded String", 
                expected, result);
    }

    @Test(expected = DecoderException.class)
    public void testDecode_InvalidType_Integer() throws DecoderException {
        // Testing the 'else' branch with an unsupported type (Integer)
        codec.decode(123);
    }

    @Test(expected = DecoderException.class)
    public void testDecode_InvalidType_Boolean() throws DecoderException {
        // Testing the 'else' branch with an unsupported type (Boolean)
        codec.decode(true);
    }

    @Test
    public void testDecode_ComplexString() throws DecoderException {
        // Testing a more complex string to ensure the underlying decode(String) works
        String input = "Hello=20World";
        String expected = "Hello World";

        Object result = codec.decode(input);

        assertEquals("Decoding complex string should work correctly", 
                expected, result);
    }

    @Test
    public void testDecode_ComplexByteArray() throws DecoderException {
        // Testing a more complex byte array
        byte[] input = "Hello=20World".getBytes();
        byte[] expected = "Hello World".getBytes();

        Object result = codec.decode(input);

        assertEquals("Decoding complex byte array should work correctly", 
                expected, result);
    }
}
